const courses = $('Read courses').all().filter(i=>i.json.status==='approved').map(i=>JSON.parse(i.json.payload));
const resources=$input.all().filter(i=>i.json.status==='approved').map(i=>JSON.parse(i.json.payload));
const aliases={robots:'robotics',robot:'robotics',programmable:'robotics',painting:'art',programming:'coding'};
function interpret(query,filters={}) {
 const q=query.toLowerCase(); const ageMatch=q.match(/\b(\d{1,2})[ -]?(?:years?[ -]?old|yr|yo)\b/)||q.match(/\bage\s*(\d{1,2})\b/);
 const terms=q.match(/[a-z]+/g)||[];
 const topics=[...new Set(terms.map(t=>aliases[t]||t).filter(t=>courses.some(c=>c.topics.includes(t))))];
 return {topics,age:filters.age?Number(filters.age):ageMatch?Number(ageMatch[1]):null,level:/beginner|intro|first/.test(q)?'Beginner':/advanced/.test(q)?'Advanced':null,location:filters.location||(/miami/.test(q)?'Miami':''),format:filters.format||(/online|virtual/.test(q)?'Online':''),subject:filters.subject||'',unknown:!!q.trim()&&topics.length===0};
}
function distanceMiles(a,b) { const r=Math.PI/180; const dLat=(b.lat-a.lat)*r,dLon=(b.lon-a.lon)*r; const x=Math.sin(dLat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dLon/2)**2;return 3958.8*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x)); }
function searchCourses(query='',filters={},catalog=courses) {
 const criteria=interpret(query,filters);
 const results=catalog.flatMap(c=>{
 if(criteria.age&&(criteria.age<c.minAge||criteria.age>c.maxAge))return [];
 if(criteria.format&&c.format!==criteria.format)return [];
 if(criteria.subject&&c.subject!==criteria.subject)return [];
 if(criteria.level&&c.level!==criteria.level)return [];
 if(criteria.location&&c.format==='Online')return [];
 const distance=criteria.location==='Miami'&&c.lat?distanceMiles({lat:25.7617,lon:-80.1918},c):null;
 if(distance!==null&&distance>25)return [];
 if(criteria.location&&criteria.location!=='Miami'&&c.city!==criteria.location)return [];
 const hits=criteria.topics.filter(t=>c.topics.includes(t));
 if(criteria.topics.length&&!hits.length)return [];
 if(criteria.unknown&&!`${c.title} ${c.subtitle} ${c.description}`.toLowerCase().includes(query.toLowerCase().trim()))return [];
 const score=hits.length*10+(criteria.age?5:0)+(criteria.level?5:0)-(distance||0)/10;
 const reasons=[hits.length?`Matches ${hits.join(', ')}`:null,criteria.age?`Suitable for age ${criteria.age}`:null,criteria.level?`${c.level} friendly`:null,distance!==null?(distance<1?'In Miami':`${Math.round(distance)} miles from Miami`):null].filter(Boolean);
 return [{...c,score,distance,reasons}];
 }).sort((a,b)=>b.score-a.score);
 return {criteria,results};
}

const q=$('Demo catalog').first().json.query||{};
const query=String(q.q||'').slice(0,500);
const filters={age:q.age||'',location:q.location||'',format:q.format||'',subject:q.subject||''};
const result=searchCourses(query,filters,courses);
const resourceQuery=String(q.resourceQuery||'').toLowerCase().slice(0,500);
const matchedResources=resources.filter(r=>(!q.resourceType||r.type===q.resourceType)&&(!q.resourceLocation||r.city===q.resourceLocation)&&(!resourceQuery||(r.title+' '+r.type+' '+r.description).toLowerCase().includes(resourceQuery)));
const selected=courses.find(c=>c.id===q.courseId);
const resourceNeeds=selected?(selected.needs||[]).map(type=>({type,matches:resources.filter(r=>r.type===type&&r.city===selected.city&&r.direction==='offered')})):[];
return [{json:{source:'n8n Data Tables',demo:true,matching:'deterministic',request_id:$execution.id,courses,resources:matchedResources,results:result.results,criteria:result.criteria,resourceNeeds,generatedAt:new Date().toISOString()}}];

const body=$json.body||{};
const get=(key,max=200)=>String(body[key]||'').trim().slice(0,max);
const kind=get('kind');if(!['Course','Resource'].includes(kind))throw new Error('Invalid submission type');
const title=get('title',120),description=get('description',2000),email=get('email');
if(title.length<3||description.length<20)throw new Error('Please provide a title and description of at least 20 characters');
if(!/^[^@\s]+@example\.(com|org|net)$/i.test(email))throw new Error('Use a fictional email at example.com, example.org, or example.net');
const request_key=get('request_key',100);if(!/^[a-zA-Z0-9_-]{8,100}$/.test(request_key))throw new Error('Invalid request key');
const allowed=['title','description','category','city','minAge','maxAge','name','email','format','schedule','readiness','needs','accommodations','transportation','direction','cost','availability'];
const data=Object.fromEntries(allowed.map(k=>[k,get(k,k==='description'?2000:500)]));
if(!data.city||!data.category)throw new Error('Location and category are required');
if(kind==='Course'&&(!Number.isInteger(Number(data.minAge))||!Number.isInteger(Number(data.maxAge))||!data.minAge||!data.maxAge||Number(data.minAge)>Number(data.maxAge)||Number(data.minAge)<5||Number(data.maxAge)>18))throw new Error('Invalid age range');
return [{json:{request_key,kind,status:'pending_review',payload:JSON.stringify({...data,demo:true,submittedAt:new Date().toISOString()})}}];
